#!/bin/bash
set -eo pipefail
sequence=19
root=/data1/home/sunyiq/kalmannet_hamid_weights_20260923_v1
date -u '+SNAPSHOT_UTC=%Y-%m-%dT%H:%M:%SZ'
state=$(sacct -X -j 227614 -n -P --format=State | sort -u | tr -d '[:space:]|')
test "$state" = "FAILED"
printf '\nOWN_JOBS_BEFORE_SUBMISSION\n'
squeue -u sunyiq -h -o '%i|%j|%T|%P|%R'
/data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -B -c "import base64;exec(base64.b64decode(''))"
bash -n "$root/diagnostic_package_20260924_v3/diagnostic.slurm"
mkdir "$root/diagnostic_submission_claim_20260924_v3"
set +e
submission_output=$(sbatch "$root/diagnostic_package_20260924_v3/diagnostic.slurm" 2>&1)
submission_exit=$?
set -e
printf '%s\n' "$submission_output" | tee "$root/diagnostic_submission_claim_20260924_v3/sbatch_output.txt"
printf '%s\n' "$submission_exit" > "$root/diagnostic_submission_claim_20260924_v3/sbatch_exit.txt"
job_id=$(printf '%s\n' "$submission_output" | sed -n 's/^Submitted batch job \([0-9][0-9]*\)$/\1/p')
if [ "$submission_exit" -ne 0 ] || ! [[ "$job_id" =~ ^[0-9]+$ ]]; then
 printf '%s\n' 'SUBMISSION_NOT_CONFIRMED_DO_NOT_RESUBMIT'
 exit 41
fi
printf '%s\n' "$job_id" > "$root/diagnostic_submission_claim_20260924_v3/job_id.txt"
printf 'DIAGNOSTIC_SUBMITTED_JOB_ID=%s\n' "$job_id"
squeue -h -j "$job_id" -o '%i|%j|%T|%R' || true
printf '\nOWN_JOBS_AFTER_SUBMISSION\n'
squeue -u sunyiq -h -o '%i|%j|%T|%P|%R'
printf '\nISOLATED_DIAGNOSTIC_SUBMISSION_COMPLETE\n'
